payload.text:
To enable atmosphere presets for the "All" (default) scene, I will update the data model to include a global `atmosphere` property on sounds, update the service layer to persist this data, and modify the UI to allow configuration and usage of these global presets.

# Updated files:

## types/index.ts

Added `atmosphere` field to the `Sound` interface.

```typescript
export type SoundType = 'Background Music' | 'Ambience' | 'One-shots';
export type AtmosphereLevel = 'Relaxed' | 'Neutral' | 'Intense';

export interface Scene {
  id: string;
  name: string;
  atmosphere?: AtmosphereLevel[] | null;
}

export interface Sound {
  id: string;
  user_id: string;
  name: string;
  file_path: string;
  publicURL?: string;
  type: SoundType;
  volume: number;
  loop: boolean;
  favorite: boolean;
  include_in_all_scenes: boolean;
  category_tag: string | null;
  mood_tag: string | null;
  location_tag: string | null;
  type_tag: string | null;
  scenes?: Scene[];
  atmosphere?: AtmosphereLevel[] | null;
  created_at: string;
}

export interface SoundSceneJoin {
    sound_id: string;
    scene_id: string;
    atmosphere: AtmosphereLevel[] | null;
}

// Fix: Add SoundboardPreset interface to resolve missing type errors.
export interface SoundboardPreset {
  id: string;
  user_id: string;
  name: string;
  sounds: Sound[];
  created_at: string;
  updated_at: string | null;
}

export interface UserProfile {
  id: string;
  username: string;
  created_at: string;
}

export interface PlayingSound {
  sound: Sound;
  source: AudioBufferSourceNode;
  gainNode: GainNode;
}
```

## lib/soundFileService.ts

Updated `uploadSoundFile` and `updateSoundFile` to handle the `atmosphere` field.

```typescript
import { supabase } from './supabase';
import { Sound, Scene, SoundSceneJoin, AtmosphereLevel, SoundType } from '../types';
import { v4 as uuidv4 } from 'https://aistudiocdn.com/uuid@^13.0.0';

// --- Scene Service Functions ---

export const getScenes = async (userId: string): Promise<Scene[]> => {
    const { data, error } = await supabase.from('scenes').select('*').eq('user_id', userId);
    if (error) {
        console.error('Error fetching scenes:', error.message);
        return [];
    }
    return data || [];
};

export const addScene = async (userId: string, name: string): Promise<Scene | null> => {
    // 1. Create Scene
    const { data: scene, error } = await supabase
        .from('scenes')
        .insert({ name: name.trim(), user_id: userId })
        .select()
        .single();

    if (error) {
        console.error('Error adding scene:', error.message);
        return null;
    }

    // 2. Find sounds that should be included in all scenes
    const { data: globalSounds } = await supabase
        .from('sound_files')
        .select('id')
        .eq('user_id', userId)
        .eq('include_in_all_scenes', true);

    // 3. Create joins for these global sounds to the new scene
    if (globalSounds && globalSounds.length > 0) {
        const newJoins = globalSounds.map(s => ({
            sound_id: s.id,
            scene_id: scene.id,
            atmosphere: [] as AtmosphereLevel[] // Default to no specific atmosphere, user can configure later
        }));

        const { error: joinError } = await supabase
            .from('sound_scene_join')
            .insert(newJoins);

        if (joinError) {
             console.error('Error auto-linking global sounds to new scene:', joinError.message);
        }
    }

    return scene;
};

export const removeScene = async (sceneId: string, userId: string): Promise<{ success: boolean; error?: string }> => {
    // 1. Delete joins first
    const { error: joinError } = await supabase
        .from('sound_scene_join')
        .delete()
        .eq('scene_id', sceneId);

    if (joinError) {
        console.error('Error deleting scene joins:', joinError.message);
        return { success: false, error: `Failed to detach sounds: ${joinError.message}` };
    }

    // 2. Delete the scene
    const { error, count } = await supabase
        .from('scenes')
        .delete({ count: 'exact' })
        .eq('id', sceneId)
        .eq('user_id', userId);

    if (error) {
        console.error('Error deleting scene:', error.message);
        return { success: false, error: error.message };
    }

    if (count === 0) {
        return { success: false, error: "Scene not found or access denied." };
    }

    return { success: true };
};

export const getSoundSceneJoins = async (userId: string): Promise<SoundSceneJoin[]> => {
    const { data: userSounds, error: soundsError } = await supabase
        .from('sound_files')
        .select('id')
        .eq('user_id', userId);

    if (soundsError) {
        console.error('Error fetching user sounds for joins:', soundsError.message);
        return [];
    }
    if (!userSounds || userSounds.length === 0) {
        return [];
    }

    const soundIds = userSounds.map(s => s.id);

    const { data, error } = await supabase
        .from('sound_scene_join')
        .select('sound_id, scene_id, atmosphere')
        .in('sound_id', soundIds);

    if (error) {
        console.error('Error fetching sound-scene joins:', error.message);
        return [];
    }
    return data || [];
}

export const updateSoundScenes = async (soundId: string, sceneData: Array<{ scene_id: string; atmosphere: AtmosphereLevel[] | null; }>): Promise<void> => {
    // Delete existing joins
    const { error: deleteError } = await supabase
        .from('sound_scene_join')
        .delete()
        .eq('sound_id', soundId);

    if (deleteError) {
        console.error('Error clearing sound scenes:', deleteError.message);
        return;
    }

    // Insert new joins
    if (sceneData.length > 0) {
        const relations = sceneData.map(data => ({
            sound_id: soundId,
            scene_id: data.scene_id,
            atmosphere: data.atmosphere
        }));
        const { error: insertError } = await supabase
            .from('sound_scene_join')
            .insert(relations);

        if (insertError) {
            console.error('Error setting sound scenes:', insertError.message);
        }
    }
};

// --- Sound File Service Functions ---

export const getSoundFiles = async (userId: string): Promise<Sound[]> => {
  const { data, error } = await supabase
    .from('sound_files')
    .select('*')
    .eq('user_id', userId)
    .order('created_at', { ascending: true });

  if (error) {
    console.error('Error fetching sound files:', error.message);
    return [];
  }

  const soundsWithUrls = data.map(sound => {
    const { data: { publicUrl } } = supabase.storage.from('sound-files').getPublicUrl(sound.file_path);
    const type = sound.type === 'Sound Effect' ? 'One-shots' : sound.type;
    return { ...sound, publicURL: publicUrl, type };
  });

  return soundsWithUrls as Sound[];
};

export const uploadSoundFile = async (
  userId: string,
  file: File,
  details: Omit<Sound, 'id' | 'user_id' | 'file_path' | 'publicURL' | 'created_at' | 'scenes' | 'favorite'> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null> }
): Promise<Sound | null> => {
  const fileExtension = file.name.split('.').pop();
  const fileName = `${uuidv4()}.${fileExtension}`;
  const filePath = `${userId}/${fileName}`;

  const { error: uploadError } = await supabase.storage
    .from('sound-files')
    .upload(filePath, file);

  if (uploadError) {
    console.error('Error uploading file:', uploadError.message);
    return null;
  }

  const { sceneIds, sceneAtmospheres, ...rest } = details;

  const dbInsertData = {
      user_id: userId,
      file_path: filePath,
      name: details.name,
      type: details.type === 'One-shots' ? 'Sound Effect' : details.type,
      volume: details.volume,
      loop: details.loop,
      include_in_all_scenes: details.include_in_all_scenes,
      category_tag: details.category_tag,
      mood_tag: details.mood_tag,
      location_tag: details.location_tag,
      type_tag: details.type_tag,
      atmosphere: details.atmosphere // Include global atmosphere
  };

  const { data, error: dbError } = await supabase
    .from('sound_files')
    .insert(dbInsertData)
    .select()
    .single();

  if (dbError) {
    console.error('Error inserting sound file metadata:', dbError.message);
    await supabase.storage.from('sound-files').remove([filePath]);
    return null;
  }

  // Handle Scenes and Atmosphere
  if (sceneIds && sceneIds.length > 0) {
      const sceneData = sceneIds.map(sceneId => ({
          scene_id: sceneId,
          atmosphere: sceneAtmospheres?.[sceneId] || null
      }));
      await updateSoundScenes(data.id, sceneData);
  }

  const { data: { publicUrl } } = supabase.storage.from('sound-files').getPublicUrl(data.file_path);
  const type = data.type === 'Sound Effect' ? 'One-shots' : data.type;
  return { ...data, publicURL: publicUrl, scenes: [], type };
};

export const updateSoundFile = async (
  id: string,
  updates: Partial<Omit<Sound, 'scenes' | 'favorite'>> & { sceneIds?: string[], sceneAtmospheres?: Record<string, AtmosphereLevel[] | null> }
): Promise<Sound | null> => {

  const allowedFields = [
      'name', 
      'type', 
      'volume', 
      'loop', 
      'include_in_all_scenes', 
      'category_tag', 
      'mood_tag', 
      'location_tag', 
      'type_tag',
      'atmosphere' // Add to allowed fields
  ];

  const dbUpdates: any = {};
  const updatesAny = updates as any;

  allowedFields.forEach(field => {
      if (updatesAny[field] !== undefined) {
          if (field === 'type' && updatesAny[field] === 'One-shots') {
              dbUpdates[field] = 'Sound Effect';
          } else {
              dbUpdates[field] = updatesAny[field];
          }
      }
  });

  let data = null;
  if (Object.keys(dbUpdates).length > 0) {
      const { data: updatedDataArray, error } = await supabase
        .from('sound_files')
        .update(dbUpdates)
        .eq('id', id)
        .select();

      if (error) {
        console.error('Error updating sound file:', error.message);
        return null;
      }
      data = updatedDataArray?.[0];
  } else {
      const { data: currentData, error } = await supabase
          .from('sound_files')
          .select()
          .eq('id', id)
          .single();
      if (!error) data = currentData;
  }

  if (!data) return null;

  if (updates.sceneIds !== undefined && updates.sceneAtmospheres !== undefined) {
      const sceneData = updates.sceneIds.map((sceneId: string) => ({
        scene_id: sceneId,
        atmosphere: updates.sceneAtmospheres?.[sceneId] || null
    }));
    await updateSoundScenes(data.id, sceneData);
  }

  const { data: { publicUrl } } = supabase.storage.from('sound-files').getPublicUrl(data.file_path);
  const type = data.type === 'Sound Effect' ? 'One-shots' : data.type;
  return { ...data, publicURL: publicUrl, scenes: [], type };
};

export const deleteSoundFile = async (sound: Sound): Promise<{ success: boolean; error?: string }> => {
  // 1. Delete sound_scene_join records first
  const { error: joinError } = await supabase
    .from('sound_scene_join')
    .delete()
    .eq('sound_id', sound.id);

  if (joinError) {
      console.error('Error deleting sound scene joins:', joinError.message);
  }

  // 2. Delete the sound file record from DB
  const { error: dbError } = await supabase
    .from('sound_files')
    .delete()
    .eq('id', sound.id);

  if (dbError) {
    console.error('Error deleting sound from DB:', dbError.message);
    return { success: false, error: `Database error: ${dbError.message} (Code: ${dbError.code})` };
  }

  // 3. Delete the actual file from storage
  const { error: storageError } = await supabase.storage
    .from('sound-files')
    .remove([sound.file_path]);

  if (storageError) {
    console.error('Error deleting sound from storage:', storageError.message);
  }

  return { success: true };
};
```

## components/AddSoundModal.tsx

Added Global Atmosphere checkboxes that appear when "Include in all scenes" is checked.

```typescript
import React, { useState, useEffect } from 'react';
import { Sound, SoundType, AtmosphereLevel, Scene } from '../types';
import { X } from 'lucide-react';

interface AddSoundModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAddSound: (file: File, details: Omit<Sound, 'id' | 'user_id' | 'file_path' | 'publicURL' | 'created_at' | 'scenes' | 'favorite'> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null>, favorite: boolean }) => Promise<void>;
  allScenes: Scene[];
}

const atmosphereLevels: AtmosphereLevel[] = ['Relaxed', 'Neutral', 'Intense'];

export const AddSoundModal: React.FC<AddSoundModalProps> = ({ isOpen, onClose, onAddSound, allScenes }) => {
  const [file, setFile] = useState<File | null>(null);
  const [name, setName] = useState('');
  const [type, setType] = useState<SoundType>('One-shots');
  const [volume, setVolume] = useState(0.75);
  const [loop, setLoop] = useState(false);
  const [favorite, setFavorite] = useState(false);
  const [includeInAllScenes, setIncludeInAllScenes] = useState(false);
  const [categoryTag, setCategoryTag] = useState('');
  const [moodTag, setMoodTag] = useState('');
  const [locationTag, setLocationTag] = useState('');
  const [typeTag, setTypeTag] = useState('');

  const [globalAtmosphere, setGlobalAtmosphere] = useState<AtmosphereLevel[]>([]);
  const [selectedSceneIds, setSelectedSceneIds] = useState<Set<string>>(new Set());
  const [sceneAtmospheres, setSceneAtmospheres] = useState<Record<string, AtmosphereLevel[]>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [showModal, setShowModal] = useState(isOpen);

  useEffect(() => {
      if (isOpen) {
          setShowModal(true);
      } else {
          const timer = setTimeout(() => setShowModal(false), 100); 
          return () => clearTimeout(timer);
      }
  }, [isOpen]);

  useEffect(() => {
      if (includeInAllScenes) {
          setSelectedSceneIds(new Set(allScenes.map(s => s.id)));
      }
  }, [includeInAllScenes, allScenes]);

  const handleSceneToggle = (sceneId: string) => {
      if (includeInAllScenes) return; 
      setSelectedSceneIds(prev => {
          const newSet = new Set(prev);
          if (newSet.has(sceneId)) {
              newSet.delete(sceneId);
          } else {
              newSet.add(sceneId);
          }
          return newSet;
      });
  };

  const handleGlobalAtmosphereChange = (level: AtmosphereLevel) => {
      setGlobalAtmosphere(prev => 
          prev.includes(level) ? prev.filter(l => l !== level) : [...prev, level]
      );
  };

  const handleSceneAtmosphereChange = (sceneId: string, level: AtmosphereLevel) => {
    setSceneAtmospheres(prev => {
      const currentLevels = prev[sceneId] || [];
      const newLevels = currentLevels.includes(level)
        ? currentLevels.filter(l => l !== level)
        : [...currentLevels, level];
      return { ...prev, [sceneId]: newLevels };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) {
      alert('Please select a sound file.');
      return;
    }
    setIsSubmitting(true);

    const finalSceneIds = Array.from(selectedSceneIds) as string[];
    const finalAtmospheres: Record<string, AtmosphereLevel[] | null> = {};

    if (type === 'Background Music' || type === 'Ambience') {
        finalSceneIds.forEach(id => {
            finalAtmospheres[id] = sceneAtmospheres[id] || [];
        });
    }

    await onAddSound(file, { 
      name: name || file.name.replace(/\.[^/.]+$/, ""), 
      type, 
      volume, 
      loop: type === 'One-shots' ? false : loop,
      favorite,
      include_in_all_scenes: includeInAllScenes,
      category_tag: type === 'Background Music' ? categoryTag || null : null,
      mood_tag: type === 'Background Music' ? moodTag || null : null,
      location_tag: type === 'Background Music' ? locationTag || null : null,
      type_tag: type === 'One-shots' ? typeTag || null : null,
      sceneIds: finalSceneIds,
      sceneAtmospheres: finalAtmospheres,
      atmosphere: includeInAllScenes ? globalAtmosphere : null,
    });

    setIsSubmitting(false);
    onClose();
    // Reset form
    setFile(null);
    setName('');
    setType('One-shots');
    setVolume(0.75);
    setLoop(false);
    setFavorite(false);
    setIncludeInAllScenes(false);
    setCategoryTag('');
    setMoodTag('');
    setLocationTag('');
    setTypeTag('');
    setSelectedSceneIds(new Set());
    setSceneAtmospheres({});
    setGlobalAtmosphere([]);
  };

  if (!showModal) return null;

  const scenesToConfigure = allScenes.filter(s => selectedSceneIds.has(s.id));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div 
        className={`absolute inset-0 bg-stone-950/40 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}
        onClick={onClose}
      />

      <div className={`relative w-full max-w-md bg-stone-900/60 backdrop-blur-2xl border border-stone-700/50 shadow-2xl rounded-3xl p-8 m-4 overflow-y-auto max-h-[90vh] custom-scrollbar ${isOpen ? 'animate-modal-in' : 'animate-modal-out'}`}>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-3xl font-medieval font-bold text-white drop-shadow-sm">Add New Sound</h2>
          <button onClick={onClose} className="text-stone-400 hover:text-white transition-colors p-2 hover:bg-stone-700/50 rounded-full"><X size={24} /></button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-stone-300 mb-1">Sound File</label>
            <input type="file" accept="audio/*" onChange={(e) => setFile(e.target.files?.[0] || null)} required className="block w-full text-sm text-stone-400 file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-sm file:font-semibold file:bg-amber-600 file:text-stone-900 hover:file:bg-amber-500 file:transition-colors cursor-pointer bg-stone-800/40 rounded-xl border border-stone-700/50"/>
          </div>
          <div>
            <label htmlFor="name" className="block text-sm font-medium text-stone-300">Sound Name</label>
            <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} placeholder={file?.name.replace(/\.[^/.]+$/, "") || "Enter name"} className="mt-1 block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 focus:ring-1 focus:ring-amber-500 outline-none transition-all"/>
          </div>

          <div>
            <label className="block text-sm font-medium text-stone-300 mb-2">Scenes</label>
            <div className="flex items-center mb-2">
                <input type="checkbox" id="includeInAllScenes" checked={includeInAllScenes} onChange={(e) => setIncludeInAllScenes(e.target.checked)} className="h-4 w-4 rounded accent-amber-500 bg-stone-700 border-stone-600" />
                <label htmlFor="includeInAllScenes" className="ml-2 text-sm text-amber-400 font-medium">Include in all scenes</label>
            </div>

            {includeInAllScenes && (type === 'Background Music' || type === 'Ambience') && (
                <div className="mb-3 p-3 bg-stone-800/40 rounded-xl border border-stone-700/50">
                    <label className="block text-sm font-medium text-stone-300 mb-2">Global Atmosphere Levels (Default)</label>
                    <div className="flex flex-wrap gap-x-4 gap-y-2">
                        {atmosphereLevels.map(level => (
                            <label key={level} className="flex items-center text-sm text-stone-300 cursor-pointer hover:text-white">
                                <input 
                                    type="checkbox" 
                                    checked={globalAtmosphere.includes(level)} 
                                    onChange={() => handleGlobalAtmosphereChange(level)}
                                    className="h-4 w-4 rounded accent-amber-500 bg-stone-700 border-stone-600"
                                />
                                <span className="ml-1.5">{level}</span>
                            </label>
                        ))}
                    </div>
                </div>
            )}

            <div className="bg-stone-800/40 border border-stone-700/50 rounded-xl p-2 max-h-32 overflow-y-auto grid grid-cols-2 gap-2 custom-scrollbar">
                {allScenes.map(scene => (
                    <label key={scene.id} className={`flex items-center text-sm text-stone-300 ${includeInAllScenes ? 'opacity-60 cursor-not-allowed' : 'cursor-pointer hover:text-white'}`}>
                        <input 
                            type="checkbox" 
                            checked={selectedSceneIds.has(scene.id)}
                            onChange={() => handleSceneToggle(scene.id)}
                            disabled={includeInAllScenes}
                            className="h-3 w-3 rounded accent-amber-500 mr-2 bg-stone-600 border-stone-500"
                        />
                        {scene.name}
                    </label>
                ))}
                {allScenes.length === 0 && <p className="text-xs text-stone-500 col-span-2 text-center">No scenes available. Create one first.</p>}
            </div>
          </div>

          <div>
            <label htmlFor="type" className="block text-sm font-medium text-stone-300">Type</label>
            <select id="type" value={type} onChange={(e) => setType(e.target.value as SoundType)} className="mt-1 block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 focus:ring-1 focus:ring-amber-500 outline-none">
              <option>Background Music</option>
              <option>Ambience</option>
              <option>One-shots</option>
            </select>
          </div>
          <div className="flex items-center gap-x-6">
            {type !== 'One-shots' && (
              <div className="flex items-center">
                <input type="checkbox" id="loop" checked={loop} onChange={(e) => setLoop(e.target.checked)} className="h-4 w-4 rounded accent-amber-500 bg-stone-700 border-stone-600" />
                <label htmlFor="loop" className="ml-2 text-sm text-stone-300">Loop</label>
              </div>
            )}
            <div className="flex items-center">
              <input type="checkbox" id="favorite" checked={favorite} onChange={(e) => setFavorite(e.target.checked)} className="h-4 w-4 rounded accent-amber-500 bg-stone-700 border-stone-600" />
              <label htmlFor="favorite" className="ml-2 text-sm text-stone-300">Favorite</label>
            </div>
          </div>

           {(type === 'Background Music' || type === 'Ambience') && scenesToConfigure.length > 0 && (
             <div className="space-y-3 p-3 bg-stone-800/40 rounded-xl max-h-48 overflow-y-auto border border-stone-700/50 custom-scrollbar">
                  <label className="block text-sm font-medium text-stone-300">Atmosphere Levels (Per Scene)</label>
                  {scenesToConfigure.map(scene => (
                      <div key={scene.id}>
                          <p className="font-semibold text-sm text-amber-400">{scene.name}</p>
                          <div className="mt-1 flex flex-wrap gap-x-4 gap-y-1">
                              {atmosphereLevels.map(level => (
                                  <label key={level} className="flex items-center text-sm text-stone-300">
                                      <input 
                                          type="checkbox" 
                                          checked={(sceneAtmospheres[scene.id] || []).includes(level)} 
                                          onChange={() => handleSceneAtmosphereChange(scene.id, level)}
                                          className="h-4 w-4 rounded accent-amber-500 bg-stone-700 border-stone-600"
                                      />
                                      <span className="ml-1.5">{level}</span>
                                  </label>
                              ))}
                          </div>
                      </div>
                  ))}
              </div>
          )}

          {type === 'Background Music' && (
             <div className="space-y-2 pt-2">
                <p className="text-sm font-medium text-stone-300">Optional Tags for Filtering</p>
                <input type="text" value={categoryTag} onChange={e => setCategoryTag(e.target.value)} placeholder="Category Tag (e.g., Combat)" className="block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 outline-none"/>
                <input type="text" value={moodTag} onChange={e => setMoodTag(e.target.value)} placeholder="Mood Tag (e.g., Tense)" className="block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 outline-none"/>
                <input type="text" value={locationTag} onChange={e => setLocationTag(e.target.value)} placeholder="Location Tag (e.g., Forest)" className="block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 outline-none"/>
             </div>
          )}
          {type === 'One-shots' && (
            <div className="space-y-2">
              <input type="text" value={typeTag} onChange={e => setTypeTag(e.target.value)} placeholder="Type Tag (e.g., Sword, Magic)" className="block w-full bg-stone-800/40 border border-stone-600/50 rounded-xl p-2 text-white focus:border-amber-500 outline-none"/>
            </div>
